export const translateKey = (key: string, lang: string = "English (US)", defaultText?: string): string => {
  return TRANSLATIONS_MAP[lang]?.[key] || TRANSLATIONS_MAP["English (US)"]?.[key] || defaultText || key;
};

export const t = (key: string, lang: string = "English (US)", defaultText?: string): string => {
  return translateKey(key, lang, defaultText);
};

export const getTranslation = translateKey;
